        # Handle specific naming conventions for event types
        lower_event = event_type.lower()
        if "deposit" in lower_event and "balance" not in updated_state and "amount" in data:
            updated_state["balance"] = updated_state.get("balance", 0) + data["amount"]
        elif "withdraw" in lower_event and "balance" not in updated_state and "amount" in data:
            updated_state["balance"] = updated_state.get("balance", 0) - data["amount"]

        if "activate" in lower_event:
            updated_state["status"] = "ACTIVE"
