            updated_state["status"] = "INACTIVE"
        elif "create" in lower_event or "register" in lower_event:
            if "status" not in updated_state:
                updated_state["status"] = "ACTIVE"

        # Record metadata if helpful
        updated_state["last_event_type"] = event_type

